// Compares the inbox with the email log: an email that has been in the inbox for more than
// backlog_minutes but is not in the log was never processed (workflow off, trigger stuck, batch limit, crash).
const cfg = $('Health settings').first().json;
const nowMs = Date.now();
const TZ = 'Asia/Amman';
const iso = (ms) => DateTime.fromMillis(ms).setZone(TZ).toISO({ suppressMilliseconds: true });

let gm = [];
try { gm = $('Gmail: recent inbox emails').all().map((i) => i.json || {}); } catch (e) { gm = []; }
const gErr = gm.find((j) => j.error);
const gmailOk = !gErr;
const gmailError = gErr ? String((gErr.error && (gErr.error.message || gErr.error.description)) || gErr.error).slice(0, 400) : '';
const inbox = gm.filter((j) => !j.error && (j.messageId || j.id));

const rows = $('Get processed emails').all().map((i) => i.json || {}).filter((r) => r.message_id);
const seen = new Set(rows.map((r) => String(r.message_id)));
const backlogMin = Number(cfg.backlog_minutes) || 15;
const received = (j) => {
  const t = Date.parse(j.date || '');
  return Number.isFinite(t) ? t : (j.internalDate ? Number(j.internalDate) : NaN);
};
const waiting = inbox
  .filter((j) => !seen.has(String(j.messageId || '')) && !seen.has(String(j.id || '')))
  .map((j) => {
    const from = (j.from && j.from.value && j.from.value[0]) || {};
    return { subject: String(j.subject || '(no subject)'), from: String(from.address || (j.from && j.from.text) || ''), age: Math.round((nowMs - received(j)) / 60000) };
  })
  .filter((x) => Number.isFinite(x.age) && x.age >= backlogMin)
  .sort((a, b) => b.age - a.age);

const times = rows.map((r) => Date.parse(r.processed_at)).filter(Number.isFinite);
const lastMs = times.length ? Math.max(...times) : null;
const day = nowMs - 24 * 3600000;
const recent = rows.filter((r) => Date.parse(r.processed_at) >= day);
const failed24 = recent.filter((r) => r.action_ok === false).length;

let status = 'ok';
if (!gmailOk || waiting.length) status = 'critical';
else if (failed24 > 0) status = 'warning';

const notes = [];
if (!gmailOk) notes.push('Could not read the inbox: ' + gmailError);
if (waiting.length) notes.push(waiting.length + ' email(s) waiting more than ' + backlogMin + ' min');
if (failed24) notes.push(failed24 + ' ClickUp action(s) failed in the last 24 h');
if (!notes.length) notes.push('All emails in the inbox (last ' + cfg.lookback_hours + ' h) were processed');

const health = {
  checked_at: iso(nowMs),
  interval_min: Number(cfg.interval_min) || 120,
  status,
  gmail_ok: gmailOk,
  gmail_error: gmailError,
  inbox_recent: inbox.length,
  backlog_count: waiting.length,
  backlog_minutes: backlogMin,
  oldest_backlog_min: waiting.length ? waiting[0].age : null,
  backlog_subjects: waiting.slice(0, 10).map((x) => x.subject + (x.from ? ' (' + x.from + ')' : '') + ', ' + x.age + ' min'),
  last_processed_at: lastMs ? iso(lastMs) : '',
  processed_24h: recent.length,
  failed_24h: failed24,
  note: notes.join('. '),
  workflow_id: String($workflow.id),
  execution_id: String($execution.id),
};

let alert = null;
const base = String(cfg.n8n_url || '').replace(/\/$/, '');
if (!gmailOk) {
  alert = {
    severity: 'critical', type: 'gmail_unreachable',
    title: 'The health check could not read the requests inbox',
    message: gmailError || 'Gmail did not answer.',
    node: 'Gmail: recent inbox emails', workflow_name: 'Email Intake → Health check', workflow_id: String($workflow.id),
    execution_id: String($execution.id), execution_url: base ? base + '/workflow/' + $workflow.id + '/executions/' + $execution.id : '',
    dedupe_key: 'gmail_unreachable|health', mode: 'live',
  };
} else if (waiting.length) {
  const w = waiting[0];
  alert = {
    severity: 'critical', type: 'backlog',
    title: waiting.length + ' email(s) waiting more than ' + backlogMin + ' min without being processed',
    message: 'Oldest: “' + w.subject + '”' + (w.from ? ' from ' + w.from : '') + ', in the inbox for ' + w.age + ' min but not in the email log. The intake workflow may be unpublished, its Gmail trigger may be failing, or more emails arrived than one run takes.',
    details: waiting.slice(0, 10).map((x) => '• ' + x.subject + (x.from ? ' (' + x.from + ')' : '') + ', ' + x.age + ' min').join('\n'),
    node: 'Gmail: new email in requests inbox', workflow_name: 'Email Intake → ClickUp (Part 1)', workflow_id: '6OEi2eVmBIKSBcmb',
    execution_url: base ? base + '/workflow/6OEi2eVmBIKSBcmb/executions' : '',
    dedupe_key: 'backlog|intake', mode: 'live',
  };
}
return [{ json: { health, alert, has_alert: !!alert, monitor_url: String(cfg.cfg_monitor_url || '').trim() } }];
